import { isNullish } from "@system";

const excludedKeys = [
  "cssVariables",
  "useCSSVariables",
  "themeScopedStyles",
  "componentVariants",
  "getSpacing",
  "toRem",
  "toPx",
  "resolveFontSize",
];
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const generateCSSVars = (theme: any, prefix = "ntx"): string => {
  let cssVars = "";

  for (const key in theme) {
    if (!excludedKeys.includes(key)) {
      if (typeof theme[key] === "object") {
        cssVars += generateCSSVars(theme[key], `${prefix}-${key}`);
      } else if (!String(theme[key]).startsWith("var(--")) {
        const cssVarName = `--${`${prefix}-${key}`.replace(
          /([a-z])([A-Z])/g,
          "$1-$2",
        )}`.toLowerCase();
        if (!isNullish(theme[key])) {
          cssVars += `${cssVarName}: ${theme[key]};\n`;
          theme[key] = `var(${cssVarName})`;
        }
      }
    }
  }

  return cssVars;
};

export default generateCSSVars;
